"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["78032"],{89747(e,t,a){a.r(t),a.d(t,{metadata:()=>n,default:()=>u,frontMatter:()=>o,contentTitle:()=>r,toc:()=>c,assets:()=>l});var n=JSON.parse('{"id":"tangfen/whatisvalue","title":"","description":"Yunguzi recently dug out the bottom of his trunk from over 30 years of research, apparently with grand ambitions to topple Marx. But unfortunately, many of his understandings are incorrect. This kind of incorrectness is actually very common. Regarding Miss Chan\'s proof, it now appears that whatever rebuttals can be raised are all inconsequential. I will have sufficient patience to accept all queries, because truth fears no questions. The same goes for the issue of Marx\'s value. But this time I\'m not speaking on anyone else\'s behalf -- let me share some of my own understanding of the value category, hoping to cast a brick to attract jade.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/tangfen/whatisvalue.md","sourceDirName":"tangfen","slug":"/tangfen/whatisvalue","permalink":"/en/tangfen/whatisvalue","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"whatisvalue","title":"","hide_table_of_contents":true,"sidebar_label":"Not speaking for anyone this time \u2014 discussing what value is with Yunguzhi!"},"sidebar":"tangfenSidebar","previous":{"title":"A summary explanation of Marx\'s value categories and labor theory of value","permalink":"/en/tangfen/basiclabortheoryofvalue"},"next":{"title":"[French Chef], the example you constructed about all finite natural numbers is invalid.","permalink":"/en/tangfen/toflxdcsf6"}}'),i=a(74848),s=a(28453);let o={id:"whatisvalue",title:"",hide_table_of_contents:!0,sidebar_label:"Not speaking for anyone this time \u2014 discussing what value is with Yunguzhi!"},r="This Time Not on Anyone's Behalf -- A Discussion with Yunguzi on What Value Is!",l={},c=[];function h(e){let t={h1:"h1",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"this-time-not-on-anyones-behalf----a-discussion-with-yunguzi-on-what-value-is",children:"This Time Not on Anyone's Behalf -- A Discussion with Yunguzi on What Value Is!"})}),"\n",(0,i.jsx)(t.p,{children:"Yunguzi recently dug out the bottom of his trunk from over 30 years of research, apparently with grand ambitions to topple Marx. But unfortunately, many of his understandings are incorrect. This kind of incorrectness is actually very common. Regarding Miss Chan's proof, it now appears that whatever rebuttals can be raised are all inconsequential. I will have sufficient patience to accept all queries, because truth fears no questions. The same goes for the issue of Marx's value. But this time I'm not speaking on anyone else's behalf -- let me share some of my own understanding of the value category, hoping to cast a brick to attract jade."}),"\n",(0,i.jsx)(t.p,{children:"Value is a historical category. Its essence is the totality of relations between people in the social structure. Any category can be examined from both qualitative and quantitative aspects. On the qualitative side, it is the intrinsic determinacy of relations between people in the social structure. On the quantitative side, it manifests in exchange as the exchange ratio between exchanged objects. The quantitative aspect of value is also called exchange value."}),"\n",(0,i.jsx)(t.p,{children:'What then is price? Price is the monetization of value. Some may ask: wasn\'t there price before currency existed? In fact, currency is also a historical category. The historical process of value taking the price form is the historical process of monetization. There is no issue of "no price before currency existed."'}),"\n",(0,i.jsx)(t.p,{children:"On the qualitative side of value, since it is the intrinsic determinacy of relations between people in the social structure, it reflects the relations between people in the social structure. The general relations between people correspond to abstract labor in the general human sense, while the particular relations between people (that is, activities between specific individuals, etc.) correspond to concrete labor in the particular sense. Abstract labor determines the general determinacy on the qualitative side of value, while concrete labor determines the particular determinacy on the qualitative side -- namely, use value."}),"\n",(0,i.jsx)(t.p,{children:"From the above it's not hard to see that Marx's value structure is very clear. It examines the value category from the standpoint of social totality, not from isolated phenomena or certain a priori premises as ordinary people do. Without standing on the standpoint of social totality and historical categories, it is impossible to truly understand Marx's labor theory of value -- note, not the labor theory of value in general, but Marx's specifically. It should also be emphasized that since many later so-called Marxists fundamentally didn't understand Marx's labor theory of value, the distinctions must be made clear."}),"\n",(0,i.jsx)(t.p,{children:"In one sentence: Marx's labor theory of value is the necessary conclusion of Marx's historical materialism. Only by standing on historical materialism can one truly understand Marx's labor theory of value. And what is commonly called historical materialism has long been castrated into a few so-called principles -- that has nothing to do with Marx!"})]})}function u(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(h,{...e})}):h(e)}},28453(e,t,a){a.d(t,{R:()=>o,x:()=>r});var n=a(96540);let i={},s=n.createContext(i);function o(e){let t=n.useContext(s);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:o(e.components),n.createElement(s.Provider,{value:t},e.children)}}}]);